text_and_chart_slide &lt;- function(slides, title, text, chart, source = NULL, footer = NULL){

  slides &lt;- slides |&gt;
    add_slide(layout = "Text and chart with source", master = "Sage Mint Theme") |&gt;
    ph_with(title, ph_location_label(ph_label = "Title 1")) |&gt;
    ph_with(text, ph_location_type(type = "body", type_idx = 2), ) |&gt;
    ph_with(chart, ph_location_type(type = "chart"))

  if(!is.null(source)){slides &lt;- slides |&gt;
    ph_with(source, ph_location_type(type = "body", type_idx = 3))
  }

  if(!is.null(footer)){slides &lt;- slides |&gt;
    ph_with(footer, ph_location_label(ph_label = "Footer"))
  }

}

